import type { FretLabGenre } from '../types/song';

export interface StyleRule {
  genre: FretLabGenre;
  bpmRange: { min: number; max: number };
  feel: 'straight' | 'shuffle' | 'swing';
  harmonicDensity: 'sparse' | 'medium' | 'dense';
  melodyDensity: 'low' | 'medium' | 'high';
  bassPattern: 'root-fifth' | 'eighths' | 'walking' | 'syncopated' | 'pedal' | 'gallop';
  drumPattern: 'rock' | 'hard-rock' | 'metal' | 'thrash' | 'groove' | 'blues' | 'funk';
  humanizationBeats: number;
  chordExtensionBias: 'triads' | 'sevenths' | 'ninths';
  phraseLengthBars: 2 | 4 | 8;
  melodyDensityPerBar: { min: number; max: number };
  pauseAfterPhraseBeats: number;
  vibratoOnPhraseEnd: boolean;
  bendUsage: 'none' | 'rare' | 'frequent';
}

