  'Thrash Metal': { genre: 'Thrash Metal', bpmRange: { min: 150, max: 210 }, feel: 'straight', harmonicDensity: 'dense', melodyDensity: 'high', bassPattern: 'gallop', drumPattern: 'thrash', humanizationBeats: 0.006, chordExtensionBias: 'triads', phraseLengthBars: 2, melodyDensityPerBar: { min: 5, max: 6 }, pauseAfterPhraseBeats: 0.5, vibratoOnPhraseEnd: false, bendUsage: 'rare' },
  'Groove Metal': { genre: 'Groove Metal', bpmRange: { min: 90, max: 130 }, feel: 'straight', harmonicDensity: 'medium', melodyDensity: 'medium', bassPattern: 'syncopated', drumPattern: 'groove', humanizationBeats: 0.018, chordExtensionBias: 'sevenths', phraseLengthBars: 4, melodyDensityPerBar: { min: 4, max: 6 }, pauseAfterPhraseBeats: 1, vibratoOnPhraseEnd: true, bendUsage: 'rare' },
  Blues: { genre: 'Blues', bpmRange: { min: 70, max: 110 }, feel: 'shuffle', harmonicDensity: 'medium', melodyDensity: 'medium', bassPattern: 'walking', drumPattern: 'blues', humanizationBeats: 0.026, chordExtensionBias: 'sevenths', phraseLengthBars: 2, melodyDensityPerBar: { min: 2, max: 3 }, pauseAfterPhraseBeats: 1.5, vibratoOnPhraseEnd: true, bendUsage: 'frequent' },
  'Blues Rock': { genre: 'Blues Rock', bpmRange: { min: 85, max: 125 }, feel: 'shuffle', harmonicDensity: 'medium', melodyDensity: 'high', bassPattern: 'walking', drumPattern: 'blues', humanizationBeats: 0.022, chordExtensionBias: 'sevenths', phraseLengthBars: 4, melodyDensityPerBar: { min: 3, max: 4 }, pauseAfterPhraseBeats: 1.5, vibratoOnPhraseEnd: true, bendUsage: 'frequent' },
  Funk: { genre: 'Funk', bpmRange: { min: 95, max: 125 }, feel: 'straight', harmonicDensity: 'dense', melodyDensity: 'medium', bassPattern: 'syncopated', drumPattern: 'funk', humanizationBeats: 0.018, chordExtensionBias: 'ninths', phraseLengthBars: 2, melodyDensityPerBar: { min: 4, max: 6 }, pauseAfterPhraseBeats: 0.5, vibratoOnPhraseEnd: false, bendUsage: 'none' },
