import type { FretLabArrangement } from '../types/song';
import { generateBassEvents, generateDrumEvents, generateMelodyEvents, type MelodyRhythm } from '../music/generators';
import { validateArrangement } from '../music/coordinator';
import { buildMusicContext } from './MusicContextEngine';

export function generateArrangement(
  arrangement: FretLabArrangement,
  melodyRhythm: MelodyRhythm = 'style',
  scaleNotes: string[],
): FretLabArrangement {
  buildMusicContext(arrangement);

  const result: FretLabArrangement = {
    ...arrangement,
    bass: generateBassEvents(arrangement),
  };
  result.drums = generateDrumEvents(result);
  result.melody = generateMelodyEvents(result, scaleNotes, melodyRhythm);

  const errors = validateArrangement(result);
  if (errors.length > 0) {
    throw new Error(`Arrangement validation failed: ${errors.join(', ')}`);
  }
  return result;
}

export function regenerateBar(
  arrangement: FretLabArrangement,
  barIndex: number,
  seed: number,
  melodyRhythm: MelodyRhythm,
  scaleNotes: string[],
): FretLabArrangement {
  const beatsPerBar = arrangement.timeSignature.beats;
  const barStart = barIndex * beatsPerBar;
  const barEnd = barStart + beatsPerBar;
  const candidate = generateArrangement(
    { ...arrangement, seed },
    melodyRhythm,
    scaleNotes,
  );

  return {
    ...arrangement,
    bass: [
      ...arrangement.bass.filter(event => event.beatStart < barStart || event.beatStart >= barEnd),
      ...candidate.bass.filter(event => event.beatStart >= barStart && event.beatStart < barEnd),
    ],
    drums: [
      ...arrangement.drums.filter(event => event.beatStart < barStart || event.beatStart >= barEnd),
      ...candidate.drums.filter(event => event.beatStart >= barStart && event.beatStart < barEnd),
    ],
    melody: [
      ...arrangement.melody.filter(event => event.beatStart < barStart || event.beatStart >= barEnd),
      ...candidate.melody.filter(event => event.beatStart >= barStart && event.beatStart < barEnd),
    ],
  };
}

export function regeneratePhrase(
  arrangement: FretLabArrangement,
  barIndex: number,
  seed: number,
  melodyRhythm: MelodyRhythm,
  scaleNotes: string[],
  phraseLengthBars: number,
): FretLabArrangement {
  const beatsPerBar = arrangement.timeSignature.beats;
  const phraseIndex = Math.floor(barIndex / phraseLengthBars);
  const startBar = phraseIndex * phraseLengthBars;
  const endBar = Math.min(arrangement.bars, startBar + phraseLengthBars);
  const barStart = startBar * beatsPerBar;
  const barEnd = endBar * beatsPerBar;
  const candidate = generateArrangement({ ...arrangement, seed }, melodyRhythm, scaleNotes);

  return {
    ...arrangement,
    bass: [
      ...arrangement.bass.filter(event => event.beatStart < barStart || event.beatStart >= barEnd),
      ...candidate.bass.filter(event => event.beatStart >= barStart && event.beatStart < barEnd),
    ],
    drums: [
      ...arrangement.drums.filter(event => event.beatStart < barStart || event.beatStart >= barEnd),
      ...candidate.drums.filter(event => event.beatStart >= barStart && event.beatStart < barEnd),
    ],
    melody: [
      ...arrangement.melody.filter(event => event.beatStart < barStart || event.beatStart >= barEnd),
      ...candidate.melody.filter(event => event.beatStart >= barStart && event.beatStart < barEnd),
    ],
  };
}
