// src/components/layout/Header.tsx

import { useState, useEffect } from 'react';
import type React from 'react';
import { isMusicMode, MUSIC_MODES, useMusic } from '../../context/MusicContext';
import { useTranslation } from '../../context/LocaleContext';
import AISearchBar from '../ai/AISearchBar';

const NOTES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

interface HeaderProps {
  onAIAction?: (action: any) => void;
}

const Header: React.FC<HeaderProps> = ({ onAIAction }) => {
  const { keyNote, mode, setKeyNote, setMode } = useMusic();
  const { t, toggleLocale, locale } = useTranslation();
  const [theme, setTheme] = useState(() => localStorage.getItem('fretlab_theme') || 'default');

  useEffect(() => {
    document.body.setAttribute('data-theme', theme);
    localStorage.setItem('fretlab_theme', theme);
  }, [theme]);

  return (
    <header className="app-header">

      <div className="header-brand">
        <div className="header-logo" aria-label="FretLab">
          <span className="header-logo__mark" aria-hidden="true">F</span>
          <span>FRETLAB</span>
        </div>
        <select
          className="header-theme-select"
          value={theme}
          onChange={(e) => setTheme(e.target.value)}
          aria-label={locale === 'ru' ? 'Цветовая тема' : 'Color theme'}
        >
          <option value="default">{t.header.themeDefault}</option>
          <option value="nebula">{t.header.themeNebula}</option>
          <option value="titanium">{t.header.themeTitanium}</option>
          <option value="crimson">{t.header.themeCrimson}</option>
        </select>
        <button
          type="button"
          className="header-locale-button"
          onClick={toggleLocale}
          aria-label={t.header.switchLang}
          title={locale === 'ru' ? t.header.switchToEn : t.header.switchToRu}
        >
          {locale === 'ru' ? 'EN' : 'RU'}
        </button>
      </div>

      <div className="header-center">
        <AISearchBar onAction={onAIAction} />
      </div>

      <div className="header-meta">
        <label className="header-meta-item">
          <span className="header-meta-label">{t.header.key}</span>
          <select
            className="fl-select header-meta-select header-meta-select--key"
            value={keyNote}
            onChange={(event) => setKeyNote(event.target.value)}
          >
            {NOTES.map(note => <option key={note} value={note}>{note}</option>)}
          </select>
        </label>
        <label className="header-meta-item">
          <span className="header-meta-label">{t.header.mode}</span>
          <select
            className="fl-select header-meta-select header-meta-select--mode"
            value={mode}
            onChange={(event) => {
              if (isMusicMode(event.target.value)) setMode(event.target.value);
            }}
          >
            {MUSIC_MODES.map(option => (
              <option key={option.value} value={option.value}>
                {locale === 'ru' ? option.ru : option.en}
              </option>
            ))}
          </select>
        </label>
      </div>

    </header>
  );
};

export default Header;